    function each(sel, fn) { if (!sel) return; for (var k in sel) { var q = Math.max(0, Math.round(+sel[k] || 0)); if (!q) continue; fn(k, q); } }
    var byName = {};
    each(kit.apparatus, function (k, q) { var it = null; for (var j = 0; j < a.apparatus.length; j++) if (a.apparatus[j].n === k) it = a.apparatus[j];
      if (!it) return; bought.push({ n: k, q: q, c: it.c, bd: it.bd, ty: it.ty, s: it.s * q }); spent += it.s * q; });
