        if (it.dff) graftMods.dff += it.dff;
        if (it.mt) graftMods.mt += it.mt;
        if (it.rt) graftMods.rtc += it.rt;
        if (it.pt) graftMods.pt += it.pt;
        if (it.fl) graftMods.flow += it.fl;
        if (it.bu) graftMods.bulk += it.bu;
